export const PIN_RACK=Object.freeze(Array.from({length:4},(_,row)=>Array.from({length:row+1},(_,i)=>({id:row*(row+1)/2+i,x:(i-row/2)*.49,z:10+row*.44}))).flat());
export function bowlingFrames(rolls){const out=[];let at=0,total=0;for(let frame=0;frame<10;frame++){const a=rolls[at];if(a===undefined)break;let value=null,used=2;if(frame===9){const count=a===10||a+(rolls[at+1]??-20)===10?3:2;if(rolls.length-at>=count)value=rolls.slice(at,at+count).reduce((n,x)=>n+x,0);used=count;}else if(a===10){used=1;if(rolls[at+1]!==undefined&&rolls[at+2]!==undefined)value=10+rolls[at+1]+rolls[at+2];}else if(rolls[at+1]!==undefined){const b=rolls[at+1];if(a+b===10){if(rolls[at+2]!==undefined)value=10+rolls[at+2];}else value=a+b;}if(value!==null)total+=value;out.push({frame:frame+1,rolls:rolls.slice(at,at+used),value,total:value===null?null:total});at+=used;}return out;}
export const bowlingScore=rolls=>bowlingFrames(rolls).reduce((n,f)=>n+(f.value??0),0);
export function splitRack(standing){if(standing.includes(0)||standing.length<2)return false;let seen=new Set([standing[0]]),queue=[standing[0]];while(queue.length){const id=queue.shift(),a=PIN_RACK[id];for(const next of standing){const b=PIN_RACK[next];if(!seen.has(next)&&Math.hypot(a.x-b.x,a.z-b.z)<.54){seen.add(next);queue.push(next);}}}return seen.size<standing.length;}
export class BowlingMatch{
 constructor({players=1,mode='quick',difficulty=3}={}){this.players=Array.from({length:players===2?2:1},(_,id)=>({id,rolls:[],frame:0,current:[],frames:[]}));this.active=0;this.standing=PIN_RACK.map(p=>p.id);this.done=false;this.phase='ready';this.history=[];this.mode=mode;this.difficulty=difficulty;this.clock=0;this.last=null;}
 begin(){if(this.done||this.phase!=='ready')return false;this.phase='rolling';return true;}
 update(dt){if(!this.done)this.clock+=Math.max(0,Math.min(.1,dt));}
 resolve(fallen){if(this.done||this.phase!=='rolling')return false;const ids=[...new Set(fallen)];if(ids.some(id=>!this.standing.includes(id)))throw Error('Invalid fallen pins.');const p=this.players[this.active],n=ids.length;p.rolls.push(n);p.current.push(n);this.standing=this.standing.filter(id=>!ids.includes(id));const frame=p.frame,turn=this.active;let complete=false,fresh=false;if(frame<9){complete=n===10||p.current.length===2;}else{const a=p.current[0],b=p.current[1];complete=p.current.length===3||p.current.length===2&&a<10&&a+b<10;fresh=!complete&&(p.current.length===1&&a===10||p.current.length===2&&(a===10&&b===10||a<10&&a+b===10));}this.last={owner:turn,frame:frame+1,roll:n,standing:[...this.standing],split:splitRack(this.standing),strike:n===10,spare:p.current.length===2&&p.current[0]<10&&p.current[0]+n===10};this.history.push(this.last);if(complete){p.frames.push([...p.current]);p.current=[];p.frame++;if(this.players.every(p=>p.frame===10)){this.done=true;this.phase='results';return{...this.last,complete:true,turnChanged:false,fresh:false};}this.active=(this.active+1)%this.players.length;fresh=true;}if(fresh)this.standing=PIN_RACK.map(p=>p.id);this.phase='ready';return{...this.last,complete,turnChanged:this.active!==turn,fresh};}
 scores(){return this.players.map(p=>bowlingScore(p.rolls));}
 winner(){const scores=this.scores();return scores.length===2&&scores[0]!==scores[1]?scores[0]>scores[1]?0:1:null;}
}
export function validBowlingRolls(rolls,score){if(!Array.isArray(rolls)||rolls.length<12||rolls.length>21)return false;const m=new BowlingMatch();for(const n of rolls){if(m.done||!Number.isInteger(n)||n<0||n>m.standing.length)return false;m.begin();m.resolve(m.standing.slice(0,n));}return m.done&&m.scores()[0]===score;}
